// Rules the brief requires, stated independently of the spec's derivation code.

const IN_FLIGHT = new Set(['queued', 'running', 'evicted']);
const FINAL_RUN = new Set(['completed', 'failed', 'cancelled']);
const TASK_STATUSES = new Set(['queued', 'running', 'evicted', 'completed', 'failed', 'cancelled']);
const tasks = (s) => [s.task0, s.task1, s.task2];
const same = (a, b) => a.status === b.status && a.task0 === b.task0 && a.task1 === b.task1 && a.task2 === b.task2;
const MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
};

export const stateInvariants = [
  { name: 'absent run has no tasks', pred: (s) => (s.status === 'absent') === tasks(s).every((t) => t === 'absent') },
  { name: 'tasks have legal statuses', pred: (s) => s.status === 'absent' || tasks(s).every((t) => TASK_STATUSES.has(t)) },
  { name: 'completed only when every task completed', pred: (s) => s.status !== 'completed' || tasks(s).every((t) => t === 'completed') },
  { name: 'failed whenever a task failed', pred: (s) => !tasks(s).includes('failed') || s.status === 'failed' },
  { name: 'never completed/cancelled with a task in flight', pred: (s) => !(s.status === 'completed' || s.status === 'cancelled') || !tasks(s).some((t) => IN_FLIGHT.has(t)) },
  { name: 'unanimous tasks give their status', pred: (s) => !(s.task0 === s.task1 && s.task1 === s.task2) || s.status === s.task0 },
  { name: 'mixed, no failure, some in flight => running', pred: (s) => {
      const ts = tasks(s);
      if (s.status === 'absent' || (ts[0] === ts[1] && ts[1] === ts[2]) || ts.includes('failed')) return true;
      return ts.some((t) => IN_FLIGHT.has(t)) ? s.status === 'running' : s.status === 'cancelled';
    } },
];

export const transitionInvariants = [
  { name: 'final run is frozen', pred: (pre, a, d, post) => !FINAL_RUN.has(pre.status) || same(pre, post) },
  { name: 'start only creates a queued run', pred: (pre, a, d, post) => a !== 'START' || (pre.status === 'absent'
      ? post.status === 'queued' && tasks(post).every((t) => t === 'queued')
      : same(pre, post)) },
  { name: 'nothing but start creates a run', pred: (pre, a, d, post) => a === 'START' || pre.status !== 'absent' || same(pre, post) },
  { name: 'task report follows its move, on its task only', pred: (pre, a, d, post) => {
      const m = MOVES[a];
      if (!m || same(pre, post)) return true;
      if (![0, 1, 2].includes(d.task)) return false;
      return [0, 1, 2].every((i) => i === d.task
        ? pre[`task${i}`] === m[0] && post[`task${i}`] === m[1]
        : pre[`task${i}`] === post[`task${i}`]);
    } },
  { name: 'cancel cancels exactly the in-flight tasks', pred: (pre, a, d, post) => {
      if (a !== 'CANCEL' || same(pre, post)) return true;
      return [0, 1, 2].every((i) => post[`task${i}`] === (IN_FLIGHT.has(pre[`task${i}`]) ? 'cancelled' : pre[`task${i}`]));
    } },
  { name: 'cancel takes effect when a live run has a task in flight', pred: (pre, a, d, post) =>
      a !== 'CANCEL' || pre.status === 'absent' || FINAL_RUN.has(pre.status) || !tasks(pre).some((t) => IN_FLIGHT.has(t)) || !same(pre, post) },
];

