test('a failed task fails the run, which still accepts commands', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  assert.deepEqual(await h.taskFailed('r', 0), OK);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'queued', task2: 'queued' });
  assert.deepEqual(await h.taskStarted('r', 1), OK);
  assert.equal((await h.run('r'))!.status, 'failed');
  assert.equal((await h.taskRetried('r', 1)).ok, false);
  assert.equal((await h.taskRetried('r', 3)).ok, false);
  assert.deepEqual(await h.taskRetried('r', 0), OK);
  assert.deepEqual(await h.run('r'), { status: 'running', task0: 'queued', task1: 'running', task2: 'queued' });
});

test('retry after all fail, and after a cancel of a failed run', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) { await h.taskStarted('r', t); await h.taskFailed('r', t); }
  assert.equal((await h.run('r'))!.status, 'failed');
  assert.equal((await h.cancel('r')).ok, false); // nothing in flight
  assert.deepEqual(await h.taskRetried('r', 2), OK);
  assert.deepEqual(await h.cancel('r'), OK);
  assert.deepEqual(await h.run('r'), { status: 'failed', task0: 'failed', task1: 'failed', task2: 'cancelled' });
  assert.deepEqual(await h.taskRetried('r', 0), OK);
  assert.deepEqual(await h.taskRetried('r', 1), OK);
  assert.equal((await h.run('r'))!.status, 'running');
  for (const t of [0, 1]) { await h.taskStarted('r', t); await h.taskCompleted('r', t); }
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'completed', task1: 'completed', task2: 'cancelled' });
  assert.equal((await h.taskRetried('r', 2)).ok, false);
});

test('completed and cancelled runs refuse everything', async () => {
  const h = await createHost();
  await h.start('r');
  await h.cancel('r');
  assert.equal((await h.run('r'))!.status, 'cancelled');
  assert.equal((await h.taskRetried('r', 0)).ok, false);
  assert.equal((await h.taskStarted('r', 0)).ok, false);
});

