// Captures real traces from src/host.impl.ts: one NDJSON window per command,
// pre/post read through the host's own run() query. Run: node spec/capture.ts
import { mkdirSync, writeFileSync, readdirSync, unlinkSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

type Snap = { status: string; task0: string; task1: string; task2: string };
const ABSENT: Snap = { status: 'absent', task0: 'absent', task1: 'absent', task2: 'absent' };
const ACTIONS = ['START', 'TASK_STARTED', 'TASK_COMPLETED', 'TASK_FAILED', 'TASK_EVICTED', 'TASK_REQUEUED', 'TASK_RETRIED', 'CANCEL'] as const;
type Action = (typeof ACTIONS)[number];

const snap = async (h: Host): Promise<Snap> => (await h.run('r')) ?? ABSENT;

async function call(h: Host, action: Action, task: number) {
  switch (action) {
    case 'START': return h.start('r');
    case 'TASK_STARTED': return h.taskStarted('r', task);
    case 'TASK_COMPLETED': return h.taskCompleted('r', task);
    case 'TASK_FAILED': return h.taskFailed('r', task);
    case 'TASK_EVICTED': return h.taskEvicted('r', task);
    case 'TASK_REQUEUED': return h.taskRequeued('r', task);
    case 'TASK_RETRIED': return h.taskRetried('r', task);
    case 'CANCEL': return h.cancel('r');
  }
}

async function scenario(steps: [Action, number?][]): Promise<string> {
  const h = await createHost();
  const lines: string[] = [];
  for (const [action, task] of steps) {
    const pre = await snap(h);
    await call(h, action, task ?? 0);
    const post = await snap(h);
    const data = action === 'START' || action === 'CANCEL' ? {} : { task };
    lines.push(JSON.stringify({ pre, action, data, post }));
  }
  return lines.join('\n') + '\n';
}

// Deterministic pseudo-random walks (LCG) plus hand-written scenarios.
function walk(seed: number, len: number): [Action, number?][] {
  let x = seed;
  const rnd = (n: number) => { x = (x * 1103515245 + 12345) % 2147483648; return x % n; };
  const steps: [Action, number?][] = [['START']];
  for (let i = 0; i < len; i++) {
    const a = ACTIONS[rnd(ACTIONS.length)];
    const t = [0, 1, 2, 3, -1][rnd(10) < 9 ? rnd(3) : 3 + rnd(2)];
    steps.push(a === 'START' || a === 'CANCEL' ? [a] : [a, t]);
  }
  return steps;
}

const S: Record<string, [Action, number?][]> = {
  happy: [['TASK_STARTED', 0], ['START'], ['START'], ['TASK_STARTED', 0], ['TASK_STARTED', 1], ['TASK_STARTED', 2],
    ['TASK_COMPLETED', 0], ['TASK_COMPLETED', 1], ['TASK_COMPLETED', 2], ['CANCEL'], ['TASK_STARTED', 0]],
  failed: [['START'], ['TASK_STARTED', 1], ['TASK_FAILED', 1], ['TASK_STARTED', 0], ['CANCEL']],
  evicted: [['START'], ['TASK_STARTED', 0], ['TASK_STARTED', 1], ['TASK_STARTED', 2], ['TASK_EVICTED', 0], ['TASK_EVICTED', 1],
    ['TASK_EVICTED', 2], ['TASK_REQUEUED', 2], ['TASK_REQUEUED', 2], ['TASK_STARTED', 2], ['TASK_COMPLETED', 2], ['CANCEL'], ['CANCEL']],
  badtask: [['START'], ['TASK_STARTED', 3], ['TASK_STARTED', -1], ['TASK_COMPLETED', 0], ['TASK_REQUEUED', 0], ['CANCEL'], ['START']],
  cancelmix: [['START'], ['TASK_STARTED', 0], ['TASK_COMPLETED', 0], ['TASK_STARTED', 1], ['CANCEL']],
};
for (let i = 0; i < 40; i++) S[`walk${String(i).padStart(2, '0')}`] = walk(i * 7919 + 1, 30);

const dir = new URL('./traces/', import.meta.url);
mkdirSync(dir, { recursive: true });
for (const f of readdirSync(dir)) if (f.endsWith('.ndjson')) unlinkSync(new URL(f, dir));
for (const [name, steps] of Object.entries(S)) writeFileSync(new URL(`${name}.ndjson`, dir), await scenario(steps));
console.log(`wrote ${Object.keys(S).length} traces`);

