// NEGATIVE CONTROL: run-status.spec.cjs with derivation rules 2 and 3 swapped
// (in flight checked before failed). The checker and the replay must both flag it.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'absent', task0: 'absent', task1: 'absent', task2: 'absent' };

const IN_FLIGHT = ['queued', 'running', 'evicted'];
const FINAL_RUN = ['completed', 'cancelled'];
const TASK_DOMAIN = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];

const derive = (ts) => {
  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
  if (ts.some((t) => IN_FLIGHT.includes(t))) return 'running';
  if (ts.includes('failed')) return 'failed';
  return 'cancelled';
};

const taskMove = (from, to) => (model) => (proposal, { reject, next }) => {
  if (model.status === 'absent') return reject('no-such-run');
  if (FINAL_RUN.includes(model.status)) return reject('run-final');
  const task = proposal.task;
  if (task !== 0 && task !== 1 && task !== 2) return reject('no-such-task');
  const ts = [model.task0, model.task1, model.task2];
  if (ts[task] !== from) return reject('illegal-move');
  ts[task] = to;
  next.task0 = ts[0];
  next.task1 = ts[1];
  next.task2 = ts[2];
  next.status = derive(ts);
};

const taskIntent = () => ({ action: (data = {}) => ({ ...data }), schema: { task: 'number' }, domain: TASK_DOMAIN });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      task0: { type: 'string' },
      task1: { type: 'string' },
      task2: { type: 'string' },
    },
    actions: {
      START: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      TASK_STARTED: taskIntent(),
      TASK_COMPLETED: taskIntent(),
      TASK_FAILED: taskIntent(),
      TASK_EVICTED: taskIntent(),
      TASK_REQUEUED: taskIntent(),
      TASK_RETRIED: taskIntent(),
      CANCEL_TASK: taskIntent(),
      CANCEL: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
    },
    acceptors: {
      START: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'absent') return reject('run-exists');
        next.status = 'queued';
        next.task0 = 'queued';
        next.task1 = 'queued';
        next.task2 = 'queued';
      },
      TASK_STARTED: taskMove('queued', 'running'),
      TASK_COMPLETED: taskMove('running', 'completed'),
      TASK_FAILED: taskMove('running', 'failed'),
      TASK_EVICTED: taskMove('running', 'evicted'),
      TASK_REQUEUED: taskMove('evicted', 'queued'),
      TASK_RETRIED: taskMove('failed', 'queued'),
      CANCEL_TASK: (model) => (proposal, { reject, next }) => {
        if (model.status === 'absent') return reject('no-such-run');
        if (FINAL_RUN.includes(model.status)) return reject('run-final');
        const task = proposal.task;
        if (task !== 0 && task !== 1 && task !== 2) return reject('no-such-task');
        const ts = [model.task0, model.task1, model.task2];
        if (!IN_FLIGHT.includes(ts[task])) return reject('task-final');
        ts[task] = 'cancelled';
        next.task0 = ts[0];
        next.task1 = ts[1];
        next.task2 = ts[2];
        next.status = derive(ts);
      },
      CANCEL: (model) => (proposal, { reject, next }) => {
        if (model.status === 'absent') return reject('no-such-run');
        if (FINAL_RUN.includes(model.status)) return reject('run-final');
        const ts = [model.task0, model.task1, model.task2];
        if (!ts.some((t) => IN_FLIGHT.includes(t))) return reject('nothing-in-flight');
        const after = ts.map((t) => (IN_FLIGHT.includes(t) ? 'cancelled' : t));
        next.task0 = after[0];
        next.task1 = after[1];
        next.task2 = after[2];
        next.status = derive(after);
      },
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  START: (data = {}) => intents.START(data),
  TASK_STARTED: (data = {}) => intents.TASK_STARTED(data),
  TASK_COMPLETED: (data = {}) => intents.TASK_COMPLETED(data),
