// Rules the brief requires, stated independently of the spec's derivation code.

const IN_FLIGHT = new Set(['queued', 'running', 'evicted']);
const FINAL_RUN = new Set(['completed', 'cancelled']); // a failed run accepts commands (change 1)
const TASK_STATUSES = new Set(['queued', 'running', 'evicted', 'completed', 'failed', 'cancelled']);
const tasks = (s) => [s.task0, s.task1, s.task2];
const same = (a, b) => a.status === b.status && a.task0 === b.task0 && a.task1 === b.task1 && a.task2 === b.task2;
const MOVES = {
  TASK_STARTED: ['queued', 'running'],
  TASK_COMPLETED: ['running', 'completed'],
  TASK_FAILED: ['running', 'failed'],
  TASK_EVICTED: ['running', 'evicted'],
  TASK_REQUEUED: ['evicted', 'queued'],
  TASK_RETRIED: ['failed', 'queued'],
};

export const stateInvariants = [
  { name: 'absent run has no tasks', pred: (s) => (s.status === 'absent') === tasks(s).every((t) => t === 'absent') },
  { name: 'tasks have legal statuses', pred: (s) => s.status === 'absent' || tasks(s).every((t) => TASK_STATUSES.has(t)) },
  { name: 'completed only when every task completed', pred: (s) => s.status !== 'completed' || tasks(s).every((t) => t === 'completed') },
  { name: 'failed whenever a task failed', pred: (s) => !tasks(s).includes('failed') || s.status === 'failed' },
  { name: 'never completed/cancelled with a task in flight', pred: (s) => !(s.status === 'completed' || s.status === 'cancelled') || !tasks(s).some((t) => IN_FLIGHT.has(t)) },
  { name: 'unanimous tasks give their status', pred: (s) => !(s.task0 === s.task1 && s.task1 === s.task2) || s.status === s.task0 },
  { name: 'mixed, no failure, some in flight => running', pred: (s) => {
      const ts = tasks(s);
      if (s.status === 'absent' || (ts[0] === ts[1] && ts[1] === ts[2]) || ts.includes('failed')) return true;
      return ts.some((t) => IN_FLIGHT.has(t)) ? s.status === 'running' : s.status === 'cancelled';
    } },
];

export const transitionInvariants = [
  { name: 'final run is frozen', pred: (pre, a, d, post) => !FINAL_RUN.has(pre.status) || same(pre, post) },
  { name: 'start only creates a queued run', pred: (pre, a, d, post) => a !== 'START' || (pre.status === 'absent'
      ? post.status === 'queued' && tasks(post).every((t) => t === 'queued')
      : same(pre, post)) },
  { name: 'nothing but start creates a run', pred: (pre, a, d, post) => a === 'START' || pre.status !== 'absent' || same(pre, post) },
  { name: 'task report follows its move, on its task only', pred: (pre, a, d, post) => {
      const m = MOVES[a];
      if (!m || same(pre, post)) return true;
      if (![0, 1, 2].includes(d.task)) return false;
      return [0, 1, 2].every((i) => i === d.task
        ? pre[`task${i}`] === m[0] && post[`task${i}`] === m[1]
        : pre[`task${i}`] === post[`task${i}`]);
    } },
  { name: 'cancel cancels exactly the in-flight tasks', pred: (pre, a, d, post) => {
      if (a !== 'CANCEL' || same(pre, post)) return true;
      return [0, 1, 2].every((i) => post[`task${i}`] === (IN_FLIGHT.has(pre[`task${i}`]) ? 'cancelled' : pre[`task${i}`]));
    } },
  { name: 'a failed task in a live run can be retried', pred: (pre, a, d, post) =>
      a !== 'TASK_RETRIED' || FINAL_RUN.has(pre.status) || pre.status === 'absent' || pre[`task${d.task}`] !== 'failed' || !same(pre, post) },
  { name: 'cancel takes effect when a live run has a task in flight', pred: (pre, a, d, post) =>
      a !== 'CANCEL' || pre.status === 'absent' || FINAL_RUN.has(pre.status) || !tasks(pre).some((t) => IN_FLIGHT.has(t)) || !same(pre, post) },
];

// Captures real traces from src/host.impl.ts: one NDJSON window per command,
// pre/post read through the host's own run() query. Run: node spec/capture.ts
import { mkdirSync, writeFileSync, readdirSync, unlinkSync } from 'node:fs';
import createHost from '../src/host.impl.ts';
import type { Host } from '../host.ts';

type Snap = { status: string; task0: string; task1: string; task2: string };
const ABSENT: Snap = { status: 'absent', task0: 'absent', task1: 'absent', task2: 'absent' };
const ACTIONS = ['START', 'TASK_STARTED', 'TASK_COMPLETED', 'TASK_FAILED', 'TASK_EVICTED', 'TASK_REQUEUED', 'TASK_RETRIED', 'CANCEL'] as const;
type Action = (typeof ACTIONS)[number];

const snap = async (h: Host): Promise<Snap> => (await h.run('r')) ?? ABSENT;

async function call(h: Host, action: Action, task: number) {
  switch (action) {
    case 'START': return h.start('r');
    case 'TASK_STARTED': return h.taskStarted('r', task);
    case 'TASK_COMPLETED': return h.taskCompleted('r', task);
    case 'TASK_FAILED': return h.taskFailed('r', task);
    case 'TASK_EVICTED': return h.taskEvicted('r', task);
    case 'TASK_REQUEUED': return h.taskRequeued('r', task);
    case 'TASK_RETRIED': return h.taskRetried('r', task);
    case 'CANCEL': return h.cancel('r');
  }
}

async function scenario(steps: [Action, number?][]): Promise<string> {
  const h = await createHost();
  const lines: string[] = [];
  for (const [action, task] of steps) {
    const pre = await snap(h);
    await call(h, action, task ?? 0);
    const post = await snap(h);
    const data = action === 'START' || action === 'CANCEL' ? {} : { task };
    lines.push(JSON.stringify({ pre, action, data, post }));
  }
  return lines.join('\n') + '\n';
}

// Deterministic pseudo-random walks (LCG) plus hand-written scenarios.
function walk(seed: number, len: number): [Action, number?][] {
  let x = seed;
  const rnd = (n: number) => { x = (x * 1103515245 + 12345) % 2147483648; return x % n; };
  const steps: [Action, number?][] = [['START']];
  for (let i = 0; i < len; i++) {
    const a = ACTIONS[rnd(ACTIONS.length)];
    const t = [0, 1, 2, 3, -1][rnd(10) < 9 ? rnd(3) : 3 + rnd(2)];
    steps.push(a === 'START' || a === 'CANCEL' ? [a] : [a, t]);
  }
  return steps;
}

const S: Record<string, [Action, number?][]> = {
  happy: [['TASK_STARTED', 0], ['START'], ['START'], ['TASK_STARTED', 0], ['TASK_STARTED', 1], ['TASK_STARTED', 2],
    ['TASK_COMPLETED', 0], ['TASK_COMPLETED', 1], ['TASK_COMPLETED', 2], ['CANCEL'], ['TASK_STARTED', 0]],
  failed: [['START'], ['TASK_STARTED', 1], ['TASK_FAILED', 1], ['TASK_STARTED', 0], ['CANCEL']],
  evicted: [['START'], ['TASK_STARTED', 0], ['TASK_STARTED', 1], ['TASK_STARTED', 2], ['TASK_EVICTED', 0], ['TASK_EVICTED', 1],
    ['TASK_EVICTED', 2], ['TASK_REQUEUED', 2], ['TASK_REQUEUED', 2], ['TASK_STARTED', 2], ['TASK_COMPLETED', 2], ['CANCEL'], ['CANCEL']],
  badtask: [['START'], ['TASK_STARTED', 3], ['TASK_STARTED', -1], ['TASK_COMPLETED', 0], ['TASK_REQUEUED', 0], ['CANCEL'], ['START']],
  retry: [['START'], ['TASK_RETRIED', 0], ['TASK_STARTED', 0], ['TASK_FAILED', 0], ['TASK_RETRIED', 1], ['TASK_RETRIED', 3],
    ['TASK_RETRIED', 0], ['TASK_STARTED', 0], ['TASK_COMPLETED', 0], ['TASK_STARTED', 1], ['TASK_COMPLETED', 1],
    ['TASK_STARTED', 2], ['TASK_COMPLETED', 2], ['TASK_RETRIED', 2]],
  allfailed: [['START'], ['TASK_STARTED', 0], ['TASK_FAILED', 0], ['TASK_STARTED', 1], ['TASK_FAILED', 1], ['TASK_STARTED', 2],
    ['TASK_FAILED', 2], ['CANCEL'], ['TASK_RETRIED', 2], ['CANCEL'], ['TASK_RETRIED', 0], ['TASK_STARTED', 0], ['TASK_COMPLETED', 0],
    ['TASK_RETRIED', 1], ['CANCEL'], ['TASK_RETRIED', 1]],
  cancelmix: [['START'], ['TASK_STARTED', 0], ['TASK_COMPLETED', 0], ['TASK_STARTED', 1], ['CANCEL']],
};
for (let i = 0; i < 40; i++) S[`walk${String(i).padStart(2, '0')}`] = walk(i * 7919 + 1, 30);

const dir = new URL('./traces/', import.meta.url);
mkdirSync(dir, { recursive: true });
for (const f of readdirSync(dir)) if (f.endsWith('.ndjson')) unlinkSync(new URL(f, dir));
for (const [name, steps] of Object.entries(S)) writeFileSync(new URL(`${name}.ndjson`, dir), await scenario(steps));
