import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

const OK = { ok: true };

test('start, duplicate start, unknown run', async () => {
  const h = await createHost();
  assert.equal(await h.run('a'), null);
  assert.deepEqual(await h.start('a'), OK);
  assert.equal((await h.start('a')).ok, false);
  assert.deepEqual(await h.run('a'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.taskStarted('b', 0)).ok, false);
  assert.equal((await h.cancel('b')).ok, false);
});

test('happy path to completed, then everything refused', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [0, 1, 2]) assert.deepEqual(await h.taskStarted('r', t), OK);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.deepEqual(await h.taskCompleted('r', 0), OK);
  assert.deepEqual(await h.taskCompleted('r', 1), OK);
  assert.equal((await h.run('r'))!.status, 'running');
  assert.deepEqual(await h.taskCompleted('r', 2), OK);
  assert.equal((await h.run('r'))!.status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
  assert.equal((await h.start('r')).ok, false);
});

test('bad task index and illegal moves refused without change', async () => {
  const h = await createHost();
  await h.start('r');
  for (const t of [-1, 3, 1.5, NaN]) assert.equal((await h.taskStarted('r', t)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  assert.equal((await h.taskRequeued('r', 0)).ok, false);
  assert.equal((await h.taskEvicted('r', 0)).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
});

test('eviction and requeue; all evicted shows evicted', async () => {
