  assert.deepEqual(await h.cancelTask('r', 2), OK);
  assert.deepEqual(await h.run('r'), { status: 'cancelled', task0: 'cancelled', task1: 'cancelled', task2: 'cancelled', paused: false });
  assert.equal((await h.cancelTask('r', 2)).ok, false);
