test('cancelTask on a failed run and next to completed tasks', async () => {
  const h = await createHost();
  await h.start('r');
  await h.taskStarted('r', 0);
  await h.taskFailed('r', 0);
  assert.equal((await h.cancelTask('r', 0)).ok, false);
  assert.deepEqual(await h.cancelTask('r', 1), OK);
  assert.equal((await h.run('r'))!.status, 'failed');
  const g = await createHost();
  await g.start('g');
  for (const t of [0, 1]) { await g.taskStarted('g', t); await g.taskCompleted('g', t); }
  assert.deepEqual(await g.cancelTask('g', 2), OK);
  assert.deepEqual(await g.run('g'), { status: 'cancelled', task0: 'completed', task1: 'completed', task2: 'cancelled', paused: false });
