test('runs are independent and hosts are fresh', async () => {
  const h = await createHost();
  await h.start('a');
  await h.start('b');
  await h.cancel('a');
  assert.equal((await h.run('b'))!.status, 'queued');
  const h2 = await createHost();
  assert.equal(await h2.run('a'), null);
