'use strict';

// SAM v2 strict-profile spec of one workflow run (src/core.ts + src/host.impl.ts).
// 'absent' stands for "no run with this id" (run() returns null); paused is false then.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const INITIAL_STATE = { status: 'absent', task0: 'absent', task1: 'absent', task2: 'absent', paused: false };

const IN_FLIGHT = ['queued', 'running', 'evicted'];
const FINAL_RUN = ['completed', 'cancelled']; // a failed run accepts commands (retry)
const TASK_DOMAIN = [{ task: 0 }, { task: 1 }, { task: 2 }, { task: 3 }, { task: -1 }];

const derive = (ts) => {
  if (ts[0] === ts[1] && ts[1] === ts[2]) return ts[0];
  if (ts.includes('failed')) return 'failed';
  if (ts.some((t) => IN_FLIGHT.includes(t))) return 'running';
  return 'cancelled';
};

const liveRun = (model, reject) => {
  if (model.status === 'absent') return reject('no-such-run');
  if (FINAL_RUN.includes(model.status)) return reject('run-final');
  return null;
};

const commitTasks = (ts, next, unchanged) => {
  next.task0 = ts[0];
  next.task1 = ts[1];
  next.task2 = ts[2];
  next.status = derive(ts);
  unchanged('paused');
};

const taskMove = (from, to) => (model) => (proposal, { reject, next, unchanged }) => {
  const refused = liveRun(model, reject);
  if (refused !== null) return refused;
  const task = proposal.task;
  if (task !== 0 && task !== 1 && task !== 2) return reject('no-such-task');
  if (from === 'queued' && to === 'running' && model.paused) return reject('run-paused');
  const ts = [model.task0, model.task1, model.task2];
  if (ts[task] !== from) return reject('illegal-move');
  ts[task] = to;
  commitTasks(ts, next, unchanged);
};

const setPaused = (paused) => (model) => (proposal, { reject, next, unchanged }) => {
  const refused = liveRun(model, reject);
  if (refused !== null) return refused;
  if (model.paused === paused) return reject(paused ? 'already-paused' : 'not-paused');
  next.paused = paused;
  unchanged('status', 'task0', 'task1', 'task2');
};

const taskIntent = () => ({ action: (data = {}) => ({ ...data }), schema: { task: 'number' }, domain: TASK_DOMAIN });
const plainIntent = () => ({ action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      status: { type: 'string' },
      task0: { type: 'string' },
      task1: { type: 'string' },
      task2: { type: 'string' },
      paused: { type: 'boolean' },
    },
    actions: {
      START: plainIntent(),
      TASK_STARTED: taskIntent(),
      TASK_COMPLETED: taskIntent(),
      TASK_FAILED: taskIntent(),
      TASK_EVICTED: taskIntent(),
      TASK_REQUEUED: taskIntent(),
      TASK_RETRIED: taskIntent(),
      CANCEL_TASK: taskIntent(),
      CANCEL: plainIntent(),
      PAUSE: plainIntent(),
      RESUME: plainIntent(),
    },
    acceptors: {
      START: (model) => (proposal, { reject, next }) => {
        if (model.status !== 'absent') return reject('run-exists');
        next.status = 'queued';
        next.task0 = 'queued';
        next.task1 = 'queued';
        next.task2 = 'queued';
        next.paused = false;
      },
      TASK_STARTED: taskMove('queued', 'running'),
      TASK_COMPLETED: taskMove('running', 'completed'),
      TASK_FAILED: taskMove('running', 'failed'),
      TASK_EVICTED: taskMove('running', 'evicted'),
      TASK_REQUEUED: taskMove('evicted', 'queued'),
      TASK_RETRIED: taskMove('failed', 'queued'),
      CANCEL_TASK: (model) => (proposal, { reject, next, unchanged }) => {
        const refused = liveRun(model, reject);
        if (refused !== null) return refused;
        const task = proposal.task;
        if (task !== 0 && task !== 1 && task !== 2) return reject('no-such-task');
        const ts = [model.task0, model.task1, model.task2];
        if (!IN_FLIGHT.includes(ts[task])) return reject('task-final');
        ts[task] = 'cancelled';
        commitTasks(ts, next, unchanged);
      },
      CANCEL: (model) => (proposal, { reject, next, unchanged }) => {
        const refused = liveRun(model, reject);
        if (refused !== null) return refused;
        const ts = [model.task0, model.task1, model.task2];
        if (!ts.some((t) => IN_FLIGHT.includes(t))) return reject('nothing-in-flight');
        commitTasks(ts.map((t) => (IN_FLIGHT.includes(t) ? 'cancelled' : t)), next, unchanged);
      },
      PAUSE: setPaused(true),
      RESUME: setPaused(false),
    },
    reactors: [],
  },
});

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  START: (data = {}) => intents.START(data),
  TASK_STARTED: (data = {}) => intents.TASK_STARTED(data),
  TASK_COMPLETED: (data = {}) => intents.TASK_COMPLETED(data),
  TASK_FAILED: (data = {}) => intents.TASK_FAILED(data),
  TASK_EVICTED: (data = {}) => intents.TASK_EVICTED(data),
  TASK_REQUEUED: (data = {}) => intents.TASK_REQUEUED(data),
  TASK_RETRIED: (data = {}) => intents.TASK_RETRIED(data),
  CANCEL_TASK: (data = {}) => intents.CANCEL_TASK(data),
  CANCEL: (data = {}) => intents.CANCEL(data),
  PAUSE: (data = {}) => intents.PAUSE(data),
  RESUME: (data = {}) => intents.RESUME(data),
};

module.exports = { instance, init, actions, getState, setState };

