// Regenerates the negative-control mutants from specs/run-status.spec.cjs.
// Each must be flagged by the checker (invariants) and by the replay (traces).
// Run: node spec/controls/make-mutants.mjs
import { readFileSync, writeFileSync } from 'node:fs';

const src = readFileSync(new URL('../specs/run-status.spec.cjs', import.meta.url), 'utf8');

const MUTANTS = {
  // derivation rules 2 and 3 swapped: in flight checked before failed
  'mutant-inflight-before-failed': [
    "  if (ts.includes('failed')) return 'failed';\n  if (ts.some((t) => IN_FLIGHT.includes(t))) return 'running';\n",
    "  if (ts.some((t) => IN_FLIGHT.includes(t))) return 'running';\n  if (ts.includes('failed')) return 'failed';\n",
  ],
  // the pause guard on taskStarted dropped
  'mutant-start-while-paused': [
    "  if (from === 'queued' && to === 'running' && model.paused) return reject('run-paused');\n",
    '',
  ],
};

for (const [name, [from, to]] of Object.entries(MUTANTS)) {
