  writeFileSync(new URL(`./${name}.cjs`, import.meta.url), `// NEGATIVE CONTROL (generated by make-mutants.mjs): ${name}\n` + src.replace(from, to));
}
console.log(`wrote ${Object.keys(MUTANTS).length} mutants`);

