    ['TASK_RETRIED', 1], ['CANCEL'], ['TASK_RETRIED', 1]],
  canceltask: [['CANCEL_TASK', 0], ['START'], ['CANCEL_TASK', 3], ['CANCEL_TASK', 0], ['CANCEL_TASK', 0], ['TASK_STARTED', 1],
    ['TASK_FAILED', 1], ['CANCEL_TASK', 1], ['TASK_STARTED', 2], ['TASK_EVICTED', 2], ['CANCEL_TASK', 2], ['TASK_RETRIED', 1],
    ['CANCEL_TASK', 1], ['CANCEL_TASK', 1]],
  canceltaskdone: [['START'], ['TASK_STARTED', 0], ['TASK_COMPLETED', 0], ['TASK_STARTED', 1], ['TASK_COMPLETED', 1],
    ['TASK_STARTED', 2], ['CANCEL_TASK', 2], ['CANCEL_TASK', 2]],
  cancelmix: [['START'], ['TASK_STARTED', 0], ['TASK_COMPLETED', 0], ['TASK_STARTED', 1], ['CANCEL']],
};
for (let i = 0; i < 40; i++) S[`walk${String(i).padStart(2, '0')}`] = walk(i * 7919 + 1, 30);

const dir = new URL('./traces/', import.meta.url);
mkdirSync(dir, { recursive: true });
for (const f of readdirSync(dir)) if (f.endsWith('.ndjson')) unlinkSync(new URL(f, dir));
for (const [name, steps] of Object.entries(S)) writeFileSync(new URL(`${name}.ndjson`, dir), await scenario(steps));
console.log(`wrote ${Object.keys(S).length} traces`);
